+package com.example;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.binder.ValueContext;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messages = new Grid<>(ContactMessage.class, false);
+    private final MessageStore messageStore;
+    private final EmailValidator emailValidator = new EmailValidator("Enter a valid e-mail address");
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        message.setMaxLength(501); // Validation, rather than client input truncation, reports the limit.
+        messages.addColumn(ContactMessage::name).setHeader("Name");
+        messages.addColumn(ContactMessage::message).setHeader("Message");
+        refreshMessages();
+
+        name.addValueChangeListener(event -> edited(name));
+        email.addValueChangeListener(event -> edited(email));
+        phone.addValueChangeListener(event -> edited(phone));
+        message.addValueChangeListener(event -> edited(message));
+
+        send.addClickListener(event -> sendMessage());
+        send.addClickShortcut(Key.ENTER);
+        add(name, email, phone, message, send, messages);
+    }
+
+    private void edited(com.vaadin.flow.component.HasValidation field) {
+        field.setInvalid(false);
+        if (!send.isEnabled()) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void sendMessage() {
+        clearValidation();
+        boolean valid = true;
+
+        if (name.getValue().isBlank()) {
+            invalid(name, "Name is required");
+            valid = false;
+        }
+
+        if (!email.getValue().isBlank()
+                && emailValidator.apply(email.getValue(), new ValueContext()).isError()) {
+            invalid(email, "Enter a valid e-mail address");
+            valid = false;
+        }
+
+        if (email.getValue().isBlank() && phone.getValue().isBlank()) {
+            invalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (message.getValue().isBlank()) {
+            invalid(message, "Message is required");
+            valid = false;
+        } else if (message.getValue().length() > 500) {
+            invalid(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(name.getValue(), email.getValue(), phone.getValue(), message.getValue()));
+        refreshMessages();
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        // clear() fires value-change events; the post-send disabled state wins.
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private void clearValidation() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        phone.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private void invalid(com.vaadin.flow.component.HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void refreshMessages() {
+        messages.setItems(messageStore.newestFirst());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty() || !message.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+        Dialog dialog = new Dialog();
+        Button keepEditing = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            action.proceed();
+        });
+        dialog.add(new Span("Discard the message you are editing?"), keepEditing, discard);
+        dialog.open();
+    }
+}
